INSERT INTO `about_us` VALUES (1,'关于我们','云南驰耀科技有限公司以物联网平台、智慧化解决方案、安防监控与信息化系统集成为核心业务方向，业务覆盖产品研发、方案设计与项目实施交付。','云南驰耀科技有限公司成立于云南楚雄高新区，是一家专注于物联网与智慧化解决方案的科技型企业。公司以「智慧物联 · 科技赋能」为使命，聚焦物联网平台研发、安防监控系统建设、智慧化解决方案设计与信息化系统集成服务。\n\n公司拥有专业的研发与项目实施团队，具备从需求分析、方案设计、产品研发到项目实施交付的全链条服务能力。公司自主研发的驰耀物联云平台与系列智能硬件产品，已在智慧园区、智慧校园、智慧安防等多个行业落地应用，获得了客户的广泛认可。\n\n驰耀科技始终秉持「客户第一、品质至上、创新驱动」的经营理念，坚持以技术创新为核心竞争力，持续为客户创造价值。','[{\"year\":\"2019\",\"title\":\"公司成立\",\"desc\":\"云南驰耀科技有限公司在昆明正式成立，专注信息化系统集成业务。\"},{\"year\":\"2020\",\"title\":\"进军安防监控\",\"desc\":\"组建安防监控事业部，承接园区、校园安防工程建设项目。\"},{\"year\":\"2021\",\"title\":\"自主研发启动\",\"desc\":\"启动物联网平台与智能硬件产品的自主研发，布局核心产品线。\"},{\"year\":\"2022\",\"title\":\"平台产品发布\",\"desc\":\"驰耀物联云平台 V1.0 正式发布，首个私有化项目落地。\"},{\"year\":\"2023\",\"title\":\"智慧方案深耕\",\"desc\":\"形成智慧园区、智慧校园、智慧安防等行业解决方案体系。\"},{\"year\":\"2024\",\"title\":\"规模增长\",\"desc\":\"完成 ISO9001 认证，服务客户覆盖西南地区多个行业。\"}]','[{\"name\":\"ISO9001\",\"desc\":\"质量管理体系认证\",\"icon\":\"award\"},{\"name\":\"高新技术企业\",\"desc\":\"国家级高新技术企业\",\"icon\":\"award\"},{\"name\":\"AAA信用企业\",\"desc\":\"企业信用评价AAA级\",\"icon\":\"shield\"},{\"name\":\"软件著作权\",\"desc\":\"多项软件产品登记\",\"icon\":\"code\"}]','[{\"name\":\"研发中心\",\"desc\":\"物联网平台与硬件研发团队 20+ 人\",\"icon\":\"cpu\"},{\"name\":\"项目实施\",\"desc\":\"资深项目经理与实施工程师团队\",\"icon\":\"tool\"},{\"name\":\"技术支持\",\"desc\":\"7×24 小时技术支持与运维服务\",\"icon\":\"headphones\"}]','2026-08-31 13:48:57'),(2,'关于我们','云南驰耀科技有限公司以物联网平台、智慧化解决方案、安防监控与信息化系统集成为核心业务方向，业务覆盖产品研发、方案设计与项目实施交付。','云南驰耀科技有限公司成立于昆明，是一家专注于物联网与智慧化解决方案的科技型企业。公司以「智慧物联 · 科技赋能」为使命，聚焦物联网平台研发、安防监控系统建设、智慧化解决方案设计与信息化系统集成服务。\n\n公司拥有专业的研发与项目实施团队，具备从需求分析、方案设计、产品研发到项目实施交付的全链条服务能力。公司自主研发的驰耀物联云平台与系列智能硬件产品，已在智慧园区、智慧校园、智慧安防等多个行业落地应用，获得了客户的广泛认可。\n\n驰耀科技始终秉持「客户第一、品质至上、创新驱动」的经营理念，坚持以技术创新为核心竞争力，持续为客户创造价值。','[{\"year\":\"2019\",\"title\":\"公司成立\",\"desc\":\"云南驰耀科技有限公司在昆明正式成立，专注信息化系统集成业务。\"},{\"year\":\"2020\",\"title\":\"进军安防监控\",\"desc\":\"组建安防监控事业部，承接园区、校园安防工程建设项目。\"},{\"year\":\"2021\",\"title\":\"自主研发启动\",\"desc\":\"启动物联网平台与智能硬件产品的自主研发，布局核心产品线。\"},{\"year\":\"2022\",\"title\":\"平台产品发布\",\"desc\":\"驰耀物联云平台 V1.0 正式发布，首个私有化项目落地。\"},{\"year\":\"2023\",\"title\":\"智慧方案深耕\",\"desc\":\"形成智慧园区、智慧校园、智慧安防等行业解决方案体系。\"},{\"year\":\"2024\",\"title\":\"规模增长\",\"desc\":\"完成 ISO9001 认证，服务客户覆盖西南地区多个行业。\"}]','[{\"name\":\"ISO9001\",\"desc\":\"质量管理体系认证\",\"icon\":\"award\"},{\"name\":\"高新技术企业\",\"desc\":\"国家级高新技术企业\",\"icon\":\"award\"},{\"name\":\"AAA信用企业\",\"desc\":\"企业信用评价AAA级\",\"icon\":\"shield\"},{\"name\":\"软件著作权\",\"desc\":\"多项软件产品登记\",\"icon\":\"code\"}]','[{\"name\":\"研发中心\",\"desc\":\"物联网平台与硬件研发团队 20+ 人\",\"icon\":\"cpu\"},{\"name\":\"项目实施\",\"desc\":\"资深项目经理与实施工程师团队\",\"icon\":\"tool\"},{\"name\":\"技术支持\",\"desc\":\"7×24 小时技术支持与运维服务\",\"icon\":\"headphones\"}]','2026-08-29 17:08:57');
