INSERT INTO `articles` VALUES (1,'company','云南驰耀科技有限公司顺利通过 ISO9001 质量管理体系认证','','公司顺利通过 ISO9001 质量管理体系认证，标志着公司在质量管理与规范运营方面迈上新台阶。','近日，云南驰耀科技有限公司顺利通过 ISO9001 质量管理体系认证评审，认证范围覆盖物联网产品研发、系统集成与技术服务全流程。\n\n此次认证的通过，是公司持续加强质量管理体系建设的重要成果，也是对公司规范化运营能力的权威认可。公司将以通过认证为契机，进一步优化产品研发与项目实施流程，为客户提供更高质量的产品与服务。','[\"企业动态\"]','驰耀科技',2,1,1,'2026-08-26 09:08:57','2026-08-29 17:08:57','2026-08-29 17:08:57'),(2,'company','云南驰耀科技有限公司顺利通过 ISO9001 质量管理体系认证','','公司顺利通过 ISO9001 质量管理体系认证，标志着公司在质量管理与规范运营方面迈上新台阶。','近日，云南驰耀科技有限公司顺利通过 ISO9001 质量管理体系认证评审，认证范围覆盖物联网产品研发、系统集成与技术服务全流程。\n\n此次认证的通过，是公司持续加强质量管理体系建设的重要成果，也是对公司规范化运营能力的权威认可。公司将以通过认证为契机，进一步优化产品研发与项目实施流程，为客户提供更高质量的产品与服务。','[\"企业动态\"]','驰耀科技',2,1,1,'2026-08-26 09:08:57','2026-08-29 17:08:57','2026-08-29 17:08:57'),(3,'tech','边缘计算在智慧园区场景中的应用实践','','边缘计算让数据在靠近源头的地方被处理，大幅降低网络压力与响应延迟，本文分享在智慧园区中的落地实践。','在智慧园区场景中，海量摄像头、传感器产生的数据如果全部上传云端处理，将带来巨大的网络带宽压力与响应延迟。边缘计算通过将数据处理下沉到靠近数据源头的边缘节点，实现了数据的本地化处理与快速响应。\n\n在驰耀科技承建的园区项目中，我们部署了边缘计算网关，在本地完成视频结构化分析、设备数据清洗与规则判断，仅将关键结果上报云端平台。实践表明，边缘计算使园区告警响应时间缩短 60% 以上，同时显著降低了云端算力与带宽成本。\n\n未来，随着 5G 与 AI 芯片的成熟，边缘计算将与云端 AI 形成更紧密的协同，推动智慧园区向更高水平的智能化演进。','[\"技术分享\"]','技术中心',0,0,1,'2026-08-23 09:08:57','2026-08-29 17:08:57','2026-08-29 17:08:57'),(4,'tech','边缘计算在智慧园区场景中的应用实践','','边缘计算让数据在靠近源头的地方被处理，大幅降低网络压力与响应延迟，本文分享在智慧园区中的落地实践。','在智慧园区场景中，海量摄像头、传感器产生的数据如果全部上传云端处理，将带来巨大的网络带宽压力与响应延迟。边缘计算通过将数据处理下沉到靠近数据源头的边缘节点，实现了数据的本地化处理与快速响应。\n\n在驰耀科技承建的园区项目中，我们部署了边缘计算网关，在本地完成视频结构化分析、设备数据清洗与规则判断，仅将关键结果上报云端平台。实践表明，边缘计算使园区告警响应时间缩短 60% 以上，同时显著降低了云端算力与带宽成本。\n\n未来，随着 5G 与 AI 芯片的成熟，边缘计算将与云端 AI 形成更紧密的协同，推动智慧园区向更高水平的智能化演进。','[\"技术分享\"]','技术中心',1,0,1,'2026-08-23 09:08:57','2026-08-29 17:08:57','2026-08-29 17:08:57'),(5,'news','驰耀科技与多家生态伙伴达成战略合作，共建物联网生态','','公司近期与多家行业伙伴签署战略合作协议，共同推进物联网与智慧化解决方案的落地应用。','为进一步拓展物联网产业生态，云南驰耀科技近期与多家行业伙伴达成战略合作，合作范围覆盖硬件终端、云服务、行业应用等多个领域。\n\n各方将依托各自在技术、产品与渠道方面的优势，围绕智慧园区、智慧校园、智慧安防等重点行业场景开展深度合作，共同打造更具竞争力的联合解决方案，为客户创造更大价值。','[\"行业资讯\"]','市场部',1,0,1,'2026-08-20 09:08:57','2026-08-29 17:08:57','2026-08-29 17:08:57'),(6,'news','驰耀科技与多家生态伙伴达成战略合作，共建物联网生态','','公司近期与多家行业伙伴签署战略合作协议，共同推进物联网与智慧化解决方案的落地应用。','为进一步拓展物联网产业生态，云南驰耀科技近期与多家行业伙伴达成战略合作，合作范围覆盖硬件终端、云服务、行业应用等多个领域。\n\n各方将依托各自在技术、产品与渠道方面的优势，围绕智慧园区、智慧校园、智慧安防等重点行业场景开展深度合作，共同打造更具竞争力的联合解决方案，为客户创造更大价值。','[\"行业资讯\"]','市场部',3,0,1,'2026-08-20 09:08:57','2026-08-29 17:08:57','2026-08-29 17:08:57'),(7,'company','驰耀科技圆满完成昆明某智慧园区项目交付验收','','公司承建的昆明某高新技术产业园区智慧化建设项目顺利通过验收，正式投入运营。','近日，由云南驰耀科技承建的昆明某高新技术产业园区智慧化建设项目顺利通过专家组验收，正式投入运营。\n\n项目历时 6 个月，完成了园区安防监控、智能通行、能耗管理、信息发布等子系统建设，并部署了园区智慧管理平台。项目投入运营后，园区安防管理效率与运营数字化水平得到显著提升，获得了园区管理方的一致好评。','[\"企业动态\"]','项目部',3,0,1,'2026-08-17 09:08:57','2026-08-29 17:08:57','2026-08-29 17:08:57'),(8,'company','驰耀科技圆满完成昆明某智慧园区项目交付验收','','公司承建的昆明某高新技术产业园区智慧化建设项目顺利通过验收，正式投入运营。','近日，由云南驰耀科技承建的昆明某高新技术产业园区智慧化建设项目顺利通过专家组验收，正式投入运营。\n\n项目历时 6 个月，完成了园区安防监控、智能通行、能耗管理、信息发布等子系统建设，并部署了园区智慧管理平台。项目投入运营后，园区安防管理效率与运营数字化水平得到显著提升，获得了园区管理方的一致好评。','[\"企业动态\"]','项目部',2,0,1,'2026-08-17 09:08:57','2026-08-29 17:08:57','2026-08-29 17:08:57'),(9,'tech','多协议融合：物联网设备接入的技术演进','','从 MQTT 到 CoAP、从私有协议到统一物模型，物联网设备接入技术正在走向多协议融合。','物联网设备接入是物联网平台的核心基础能力。早期物联网系统多采用厂商私有协议，导致设备难以互通、平台难以扩展。随着行业标准化进程推进，MQTT、CoAP、HTTP 等标准协议逐渐成为主流。\n\n驰耀物联网云平台采用多协议接入架构，同时支持 MQTT、CoAP、HTTP 与主流厂商私有协议，并通过统一物模型屏蔽协议差异，使上层应用无需关心设备接入细节。平台还提供协议插件机制，支持新协议的快速扩展接入。\n\n多协议融合既是技术趋势，也是现实需求。统一的设备接入能力，将帮助企业更灵活地构建自己的物联网应用。','[\"技术分享\"]','技术中心',2,0,1,'2026-08-14 09:08:57','2026-08-29 17:08:57','2026-08-29 17:08:57'),(10,'tech','多协议融合：物联网设备接入的技术演进','','从 MQTT 到 CoAP、从私有协议到统一物模型，物联网设备接入技术正在走向多协议融合。','物联网设备接入是物联网平台的核心基础能力。早期物联网系统多采用厂商私有协议，导致设备难以互通、平台难以扩展。随着行业标准化进程推进，MQTT、CoAP、HTTP 等标准协议逐渐成为主流。\n\n驰耀物联网云平台采用多协议接入架构，同时支持 MQTT、CoAP、HTTP 与主流厂商私有协议，并通过统一物模型屏蔽协议差异，使上层应用无需关心设备接入细节。平台还提供协议插件机制，支持新协议的快速扩展接入。\n\n多协议融合既是技术趋势，也是现实需求。统一的设备接入能力，将帮助企业更灵活地构建自己的物联网应用。','[\"技术分享\"]','技术中心',2,0,1,'2026-08-14 09:08:57','2026-08-29 17:08:57','2026-08-29 17:08:57'),(11,'news','政策解读：新基建驱动下智慧园区建设的市场机遇','','新型基础设施建设持续推进，智慧园区作为数字经济的重要载体迎来新的发展机遇。','随着新型基础设施建设的持续推进，智慧园区建设进入快速发展期。国家层面相继出台多项政策，支持园区数字化、智能化转型，为相关产业链企业带来广阔市场空间。\n\n从需求侧看，园区运营方对安防升级、能耗管理、智慧通行、运营效率提升的需求日益迫切；从供给侧看，物联网、AI、大数据等技术的成熟为智慧园区落地提供了坚实支撑。\n\n驰耀科技将持续深耕智慧园区赛道，以「平台+生态」的战略思路，与合作伙伴共同服务园区数字化转型。','[\"行业资讯\"]','市场部',2,0,1,'2026-08-11 09:08:57','2026-08-29 17:08:57','2026-08-29 17:08:57'),(12,'news','政策解读：新基建驱动下智慧园区建设的市场机遇','','新型基础设施建设持续推进，智慧园区作为数字经济的重要载体迎来新的发展机遇。','随着新型基础设施建设的持续推进，智慧园区建设进入快速发展期。国家层面相继出台多项政策，支持园区数字化、智能化转型，为相关产业链企业带来广阔市场空间。\n\n从需求侧看，园区运营方对安防升级、能耗管理、智慧通行、运营效率提升的需求日益迫切；从供给侧看，物联网、AI、大数据等技术的成熟为智慧园区落地提供了坚实支撑。\n\n驰耀科技将持续深耕智慧园区赛道，以「平台+生态」的战略思路，与合作伙伴共同服务园区数字化转型。','[\"行业资讯\"]','市场部',2,0,1,'2026-08-11 09:08:57','2026-08-29 17:08:57','2026-08-29 17:08:57');
