INSERT INTO `cases` VALUES (1,2,'昆明某高新技术产业园区智慧化建设项目','','[]','为该园区建设覆盖安防、通行、能耗、信息发布的一体化智慧管理平台，实现园区运营数字化。','本项目为园区建设了以驰耀物联云平台为核心的智慧管理系统，部署高清摄像机 600+ 路、门禁点位 120 个、能耗监测点 200+ 个，并建设园区运营指挥中心。项目实现了园区安防统一管理、访客线上预约、能耗精细化统计与信息一键发布。','[\"智慧园区\",\"安防监控\",\"物联网平台\"]','[[\"600+\",\"高清监控点位\"],[\"120\",\"门禁管理点位\"],[\"40%\",\"能耗同比节约\"],[\"7×24\",\"全天候智能值守\"]]','[]','[]',1,1,'昆明某高新技术产业园区智慧化建设项目','','','2026-08-29 17:08:57','2026-08-29 17:08:57'),(2,2,'昆明某高新技术产业园区智慧化建设项目','','[]','为该园区建设覆盖安防、通行、能耗、信息发布的一体化智慧管理平台，实现园区运营数字化。','本项目为园区建设了以驰耀物联云平台为核心的智慧管理系统，部署高清摄像机 600+ 路、门禁点位 120 个、能耗监测点 200+ 个，并建设园区运营指挥中心。项目实现了园区安防统一管理、访客线上预约、能耗精细化统计与信息一键发布。','[\"智慧园区\",\"安防监控\",\"物联网平台\"]','[[\"600+\",\"高清监控点位\"],[\"120\",\"门禁管理点位\"],[\"40%\",\"能耗同比节约\"],[\"7×24\",\"全天候智能值守\"]]','[]','[]',1,1,'昆明某高新技术产业园区智慧化建设项目','','','2026-08-29 17:08:57','2026-08-29 17:08:57'),(3,4,'云南某高校平安校园安防系统工程','','[]','为高校建设覆盖教学区、宿舍区、图书馆等重点区域的平安校园安防体系。','项目为高校建设了以视频监控为核心，融合人脸识别、入侵报警、访客管理、电子巡查的安防体系，覆盖全校 32 栋建筑，部署智能摄像机 800+ 路。通过 AI 智能分析实现重点区域 24 小时值守与异常事件自动告警，全面提升了校园安全防范能力。','[\"智慧教育\",\"人脸识别\",\"安防监控\"]','[[\"800+\",\"智能监控点位\"],[\"32\",\"栋建筑覆盖\"],[\"100%\",\"重点区域覆盖\"],[\"<30s\",\"告警响应时间\"]]','[]','[]',1,2,'云南某高校平安校园安防系统工程','','','2026-08-29 17:08:57','2026-08-29 17:08:57'),(4,4,'云南某高校平安校园安防系统工程','','[]','为高校建设覆盖教学区、宿舍区、图书馆等重点区域的平安校园安防体系。','项目为高校建设了以视频监控为核心，融合人脸识别、入侵报警、访客管理、电子巡查的安防体系，覆盖全校 32 栋建筑，部署智能摄像机 800+ 路。通过 AI 智能分析实现重点区域 24 小时值守与异常事件自动告警，全面提升了校园安全防范能力。','[\"智慧教育\",\"人脸识别\",\"安防监控\"]','[[\"800+\",\"智能监控点位\"],[\"32\",\"栋建筑覆盖\"],[\"100%\",\"重点区域覆盖\"],[\"<30s\",\"告警响应时间\"]]','[]','[]',1,2,'云南某高校平安校园安防系统工程','','','2026-08-29 17:08:57','2026-08-29 17:08:57'),(5,7,'云南某制造企业数字化监控与设备联网项目','','[]','帮助制造企业实现生产设备联网与可视化监控，打通生产数据链路。','项目为该制造企业 3 条核心产线的 86 台设备进行联网改造，部署边缘计算网关采集设备运行数据，建设企业数字化监控平台，实现生产进度、设备状态、能耗数据的实时可视化，并通过告警联动大幅缩短了故障响应时间。','[\"智能制造\",\"设备联网\",\"数据可视化\"]','[[\"86\",\"台设备联网\"],[\"3\",\"条产线覆盖\"],[\"95%\",\"设备联网率\"],[\"70%\",\"故障响应提速\"]]','[]','[]',1,3,'云南某制造企业数字化监控与设备联网项目','','','2026-08-29 17:08:57','2026-08-29 17:08:57'),(6,8,'云南某制造企业数字化监控与设备联网项目','','[]','帮助制造企业实现生产设备联网与可视化监控，打通生产数据链路。','项目为该制造企业 3 条核心产线的 86 台设备进行联网改造，部署边缘计算网关采集设备运行数据，建设企业数字化监控平台，实现生产进度、设备状态、能耗数据的实时可视化，并通过告警联动大幅缩短了故障响应时间。','[\"智能制造\",\"设备联网\",\"数据可视化\"]','[[\"86\",\"台设备联网\"],[\"3\",\"条产线覆盖\"],[\"95%\",\"设备联网率\"],[\"70%\",\"故障响应提速\"]]','[]','[]',1,3,'云南某制造企业数字化监控与设备联网项目','','','2026-08-29 17:08:57','2026-08-29 17:08:57'),(7,1,'曲靖某智慧物流园区监控与车辆管理系统项目','','[]','为大型物流园区建设车辆识别、视频监控、周界防范一体化系统。','为占地500亩的物流园区建设智慧化系统，包含出入口道闸与车牌识别、视频监控AI分析、周界防范、仓库智能值守等子系统。通过驰耀物联云平台实现数据联动。','[\"智慧园区\",\"物流仓储\",\"车辆识别\"]','[[\"500+\",\"监控点位覆盖\"],[\"4\",\"进出入大门\"],[\"10秒内\",\"车辆过闸放行\"],[\"99.8%\",\"车牌识别准确率\"]]','[]','[]',1,4,'曲靖某智慧物流园区监控与车辆管理系统项目','','','2026-08-31 13:04:44','2026-08-31 13:04:44'),(8,3,'昆明某中学智慧校园安防与一卡通项目','','[]','为中学建设安防监控、人脸门禁、校园一卡通、访客管理系统。','部署智能摄像机300余路、校门与宿舍楼人脸门禁，实现学生刷脸进出与考勤。一卡通覆盖食堂、图书馆、热水等场景，访客系统实现线上预约与自动授权。','[\"智慧教育\",\"一卡通\",\"人脸门禁\"]','[[\"300+\",\"监控点位\"],[\"6\",\"栋宿舍人脸门禁\"],[\"1\",\"卡通覆盖全场景\"],[\"50%\",\"安保人力节省\"]]','[]','[]',1,5,'昆明某中学智慧校园安防与一卡通项目','','','2026-08-31 13:04:44','2026-08-31 13:04:44'),(9,7,'玉溪某卷烟辅料企业能源管理与设备联网项目','','[]','部署能源管理系统与生产设备联网，实现能耗精细化管理。','对配电、水、压缩空气系统分项计量改造，采集38台主要设备运行数据，建设能源与设备监控平台。通过数据分析发现多处压缩空气泄漏与设备空载浪费，节能改造后收益明显。','[\"智能制造\",\"能源管理\",\"设备联网\"]','[[\"38\",\"台设备联网监控\"],[\"126\",\"个能耗计量点\"],[\"18%\",\"综合能耗下降\"],[\"8个月\",\"投资回收周期\"]]','[]','[]',1,6,'玉溪某卷烟辅料企业能源管理与设备联网项目','','','2026-08-31 13:04:44','2026-08-31 13:04:44'),(10,5,'大理某旅游景区智慧安防与客流管控系统','','[]','为5A级景区建设视频监控、客流统计、应急广播、一键求助系统。','覆盖景区20余平方公里，部署高清摄像机280余路、客流统计20处、应急广播与一键求助60余个。支持实时客流热力图、人员密度预警、应急事件一键联动广播。','[\"智慧安防\",\"旅游景区\",\"客流管控\"]','[[\"280+\",\"路摄像机\"],[\"60+\",\"一键求助柱\"],[\"<2分钟\",\"应急响应时间\"],[\"0\",\"重大安全事故\"]]','[]','[]',1,7,'大理某旅游景区智慧安防与客流管控系统','','','2026-08-31 13:04:44','2026-08-31 13:04:44');
