INSERT INTO `downloads` VALUES (1,3,'驰耀物联云平台使用手册','doc','驰耀物联云平台完整使用手册，涵盖平台注册、设备接入、数据管理、规则引擎配置等内容。','本手册面向平台管理员与开发者，系统介绍驰耀物联云平台的功能模块与操作流程，包括设备接入指引、规则引擎配置、告警联动设置、数据大屏搭建等章节，并附常见问题解答。','V3.0.2','[[\"驰耀物联云平台使用手册.pdf\",\"PDF\",\"12.8MB\"]]','12.8MB','2024-11-20 更新：补充设备接入协议章节','支持 Windows / macOS / Linux，建议使用 Chrome、Edge 等现代浏览器',5,'[]',1,1,'驰耀物联云平台使用手册','','','2026-08-29 17:08:57','2026-08-29 17:08:57'),(2,1,'网络摄像机 Windows 客户端驱动','camera','网络摄像机 Windows 客户端安装程序，支持设备搜索、预览、回放与参数配置。','该客户端用于网络摄像机的日常管理与配置，支持自动搜索局域网设备、多路预览、录像回放、云台控制与参数修改。','V1.8.0','[[\"CY_IPC_Win_Client_v1.8.0.zip\",\"ZIP\",\"56.3MB\"]]','56.3MB','2024-12-01 更新：修复设备搜索偶发失败问题','Windows 10/11 (64位)，4GB 以上内存',1,'[]',1,2,'网络摄像机 Windows 客户端驱动','','','2026-08-29 17:08:57','2026-08-29 17:08:57'),(3,2,'边缘计算智能网关固件包','chip','边缘计算智能网关 CY-EG200 固件升级包，优化协议解析性能并新增断网续传能力。','本固件适用于 CY-EG200 边缘计算智能网关，升级后新增 5G 网络支持、断网续传增强与协议解析性能优化。升级前请备份配置文件。','V2.4.1','[[\"CY-EG200_FW_V2.4.1.img\",\"IMG\",\"48.2MB\"]]','48.2MB','2024-12-10 发布：新增断网续传增强功能','适用于 CY-EG200 网关硬件，通过 Web 管理界面升级',1,'[]',1,3,'边缘计算智能网关固件包','','','2026-08-29 17:08:57','2026-08-29 17:08:57'),(4,4,'驰耀物联网开放平台 SDK (Java)','code','Java 版开放平台 SDK，提供设备管理、数据上报、命令下发等接口封装，快速接入业务系统。','Java SDK 封装了驰耀物联网开放平台的核心 API，支持设备注册、数据上报订阅、命令下发、告警回调等功能，提供完整示例代码与 API 文档。','V2.1.0','[[\"chiyao-iot-sdk-java-v2.1.0.zip\",\"ZIP\",\"3.6MB\"],[\"chiyao-iot-openapi-javadoc.pdf\",\"PDF\",\"2.1MB\"]]','5.7MB','2024-11-05 发布：支持 JDK 8+ 与 Spring Boot 集成','JDK 8+，Maven 3.6+',0,'[]',1,4,'驰耀物联网开放平台 SDK (Java)','','','2026-08-29 17:08:57','2026-08-29 17:08:57'),(5,4,'驰耀物联网开放平台 SDK (Python)','code','Python 版开放平台 SDK，支持异步接口，适用于数据采集与自动化脚本场景。','Python SDK 基于 asyncio 实现，支持异步设备数据上报、命令下发与告警处理，提供清晰的类型提示与文档。','V1.9.0','[[\"chiyao-iot-sdk-python-v1.9.0.tar.gz\",\"TAR.GZ\",\"2.4MB\"]]','2.4MB','2024-10-18 发布：新增异步批量查询接口','Python 3.8+，支持 pip 安装',0,'[]',1,5,'驰耀物联网开放平台 SDK (Python)','','','2026-08-29 17:08:57','2026-08-29 17:08:57'),(6,5,'驰耀物联网平台设备接入协议文档','doc','面向设备厂商与开发者的设备接入协议规范文档，详细说明 MQTT/HTTP 接入流程与数据格式。','本文档详细定义设备接入驰耀物联网平台的协议规范，包括设备认证、消息主题、数据报文格式、上下线机制与错误码说明，是设备接入开发的必备参考资料。','V1.6.0','[[\"chiyao-iot-protocol-spec-v1.6.0.pdf\",\"PDF\",\"8.9MB\"]]','8.9MB','2024-11-28 更新：补充 5G 模组接入章节','无特殊要求',0,'[]',1,6,'驰耀物联网平台设备接入协议文档','','','2026-08-29 17:08:57','2026-08-29 17:08:57'),(7,5,'驰耀开放平台 API 接口文档','api','驰耀物联云开放平台完整 REST API 接口文档，供第三方系统对接使用。','详细介绍所有对外 REST API 接口，包括设备管理、数据查询、命令下发、告警、组织与用户管理等接口，附带请求示例与返回字段说明。','V3.0','[[\"驰耀开放平台API文档V3.0.pdf\",\"PDF\",\"8.6MB\"]]','8.6MB','2024-12-05 更新：新增批量命令下发与历史数据聚合查询接口','开发者需先在平台申请 API Key，支持 HTTP/HTTPS 调用',0,'[]',1,7,'驰耀开放平台 API 接口文档','','','2026-08-31 13:04:44','2026-08-31 13:04:44'),(8,4,'Android 移动端 SDK 开发包','code','Android 平台 SDK，便于移动端 App 快速集成物联网平台能力。','提供用户登录、设备列表、实时数据订阅、命令下发、告警推送等功能封装。采用Kotlin编写，兼容Java调用，附带完整Demo工程。','V1.4.0','[[\"chiyao-iot-sdk-android-v1.4.0.zip\",\"ZIP\",\"6.2MB\"]]','6.2MB','2024-11-28 发布：新增 WebSocket 实时数据推送，修复已知问题','Android 6.0+ (API Level 23+)，推荐使用 Android Studio',0,'[]',1,8,'Android 移动端 SDK 开发包','','','2026-08-31 13:04:44','2026-08-31 13:04:44'),(9,3,'边缘计算智能网关配置手册','doc','CY-EG200 边缘计算网关用户配置手册，含接线、参数配置、协议对接。','详细介绍CY-EG200系列网关的硬件接口、上电启动、本地Web配置、平台接入流程、200+工业协议配置、断网续传、固件升级等内容，是实施工程师必备资料。','V2.1','[[\"CY-EG200边缘计算网关配置手册V2.1.pdf\",\"PDF\",\"15.3MB\"]]','15.3MB','2024-10-25 更新：新增西门子S7协议与BACnet协议配置章节','适用于 CY-EG200 V2.x 硬件版本，建议使用 Chrome 浏览器',0,'[]',1,9,'边缘计算智能网关配置手册','','','2026-08-31 13:04:44','2026-08-31 13:04:44'),(10,2,'网络摄像机 IPC 固件升级包 V5.6.13','chip','CY-IPC200/CY-IPC400 系列智能网络摄像机最新固件升级包。','针对CY-IPC200/400系列摄像机，修复已知问题并优化算法性能。升级前确保接入稳定网络并保持供电，过程约3-5分钟，期间请勿断电。','V5.6.13','[[\"IPC_CY-IPC200-400_V5.6.13.dav\",\"DAV\",\"34.8MB\"]]','34.8MB','修复：1)夜视切换异常；2)优化人脸识别精度；3)增加ONVIF Profile T；4)定时重启偶发失效','适用于 CY-IPC200 / CY-IPC400 系列机型，升级前版本需 ≥ V5.3.00',0,'[]',1,10,'网络摄像机 IPC 固件升级包 V5.6.13','','','2026-08-31 13:04:44','2026-08-31 13:04:44');
