INSERT INTO `products` VALUES (1,3,'驰耀物联云平台','CY-IoT V3.0','','[]','面向行业应用的物联网设备连接与管理平台，支持百万级设备接入、实时数据采集、规则引擎与可视化大屏。','驰耀物联云平台是一款集设备接入、数据管理、业务应用于一体的物联网基础平台。平台基于微服务架构，支持 MQTT、CoAP、HTTP 等多种接入协议，提供设备管理、数据采集、告警联动、规则引擎、数据可视化等核心能力，可广泛应用于智慧园区、智慧农业、智慧工业等场景。平台提供开放 API 与标准 SDK，支持与第三方业务系统快速集成。','[[\"设备接入能力\",\"百万级设备并发接入\"],[\"支持协议\",\"MQTT / CoAP / HTTP / TCP\"],[\"数据吞吐\",\"10万级消息/秒\"],[\"部署方式\",\"公有云 / 私有化部署\"],[\"开放能力\",\"REST API + SDK\"],[\"可视化\",\"数据大屏 / 3D 场景\"]]','[]',1,1,'驰耀物联云平台','','','2026-08-29 17:08:57','2026-08-29 17:08:57'),(2,3,'驰耀物联云平台','CY-IoT V3.0','','[]','面向行业应用的物联网设备连接与管理平台，支持百万级设备接入、实时数据采集、规则引擎与可视化大屏。','驰耀物联云平台是一款集设备接入、数据管理、业务应用于一体的物联网基础平台。平台基于微服务架构，支持 MQTT、CoAP、HTTP 等多种接入协议，提供设备管理、数据采集、告警联动、规则引擎、数据可视化等核心能力，可广泛应用于智慧园区、智慧农业、智慧工业等场景。平台提供开放 API 与标准 SDK，支持与第三方业务系统快速集成。','[[\"设备接入能力\",\"百万级设备并发接入\"],[\"支持协议\",\"MQTT / CoAP / HTTP / TCP\"],[\"数据吞吐\",\"10万级消息/秒\"],[\"部署方式\",\"公有云 / 私有化部署\"],[\"开放能力\",\"REST API + SDK\"],[\"可视化\",\"数据大屏 / 3D 场景\"]]','[]',1,1,'驰耀物联云平台','','','2026-08-29 17:08:57','2026-08-29 17:08:57'),(3,3,'驰耀可视化大屏系统','CY-Dashboard','','[]','灵活配置的数据可视化大屏系统，拖拽式搭建，实时数据展示，适配各类指挥中心与展示大屏。','可视化大屏系统提供丰富的图表组件与行业模板，通过拖拽式编辑器即可快速搭建数据大屏。系统支持实时数据推送、地图联动、多屏协同，可对接各类业务数据库与物联网平台，广泛应用于指挥中心、运营监控、展厅展示等场景。','[[\"组件库\",\"50+ 可视化组件\"],[\"数据源\",\"MySQL / API / MQTT / WebSocket\"],[\"布局方式\",\"拖拽式自由布局\"],[\"多屏联动\",\"支持多屏同步展示\"]]','[]',1,2,'驰耀可视化大屏系统','','','2026-08-29 17:08:57','2026-08-29 17:08:57'),(4,3,'驰耀物联云平台','CY-IoT V3.0','','[]','面向行业应用的物联网设备连接与管理平台，支持百万级设备接入、实时数据采集、规则引擎与可视化大屏。','驰耀物联云平台是一款集设备接入、数据管理、业务应用于一体的物联网基础平台。平台基于微服务架构，支持 MQTT、CoAP、HTTP 等多种接入协议，提供设备管理、数据采集、告警联动、规则引擎、数据可视化等核心能力，可广泛应用于智慧园区、智慧农业、智慧工业等场景。平台提供开放 API 与标准 SDK，支持与第三方业务系统快速集成。','[[\"设备接入能力\",\"百万级设备并发接入\"],[\"支持协议\",\"MQTT / CoAP / HTTP / TCP\"],[\"数据吞吐\",\"10万级消息/秒\"],[\"部署方式\",\"公有云 / 私有化部署\"],[\"开放能力\",\"REST API + SDK\"],[\"可视化\",\"数据大屏 / 3D 场景\"]]','[]',1,1,'驰耀物联云平台','','','2026-08-29 17:08:57','2026-08-29 17:08:57'),(5,3,'驰耀可视化大屏系统','CY-Dashboard','','[]','灵活配置的数据可视化大屏系统，拖拽式搭建，实时数据展示，适配各类指挥中