INSERT INTO `solutions` VALUES (1,'智慧园区解决方案','智慧园区','','[]','面向产业园区、办公园区的一体化智慧运营方案，实现安防、能耗、停车、访客等场景的数字化管理。','智慧园区解决方案以「1个平台 + N个应用」为架构，融合物联网感知、视频AI、大数据分析等技术，建设智慧安防、智慧通行、智慧能耗、智慧办公等应用，全面提升园区运营效率与安全水平。','适用于产业园区、科技园区、办公园区、物流园区等场景，解决安防管理分散、能耗浪费、通行效率低、运营数据不透明等痛点。','感知层（IPC/门禁/传感器）→ 网络层（有线/无线/物联网）→ 平台层（驰耀物联云平台）→ 应用层（安防/能耗/通行/办公）→ 展示层（运营大屏/移动端）','[\"安防事件响应时间缩短 60%\",\"园区能耗降低 20%\",\"通行效率提升 45%\",\"运营数据一屏可视\"]','[]','[]',1,1,'智慧园区解决方案','','','2026-08-29 17:08:57','2026-08-29 17:08:57'),(2,'智慧园区解决方案','智慧园区','','[]','面向产业园区、办公园区的一体化智慧运营方案，实现安防、能耗、停车、访客等场景的数字化管理。','智慧园区解决方案以「1个平台 + N个应用」为架构，融合物联网感知、视频AI、大数据分析等技术，建设智慧安防、智慧通行、智慧能耗、智慧办公等应用，全面提升园区运营效率与安全水平。','适用于产业园区、科技园区、办公园区、物流园区等场景，解决安防管理分散、能耗浪费、通行效率低、运营数据不透明等痛点。','感知层（IPC/门禁/传感器）→ 网络层（有线/无线/物联网）→ 平台层（驰耀物联云平台）→ 应用层（安防/能耗/通行/办公）→ 展示层（运营大屏/移动端）','[\"安防事件响应时间缩短 60%\",\"园区能耗降低 20%\",\"通行效率提升 45%\",\"运营数据一屏可视\"]','[]','[]',1,1,'智慧园区解决方案','','','2026-08-29 17:08:57','2026-08-29 17:08:57'),(3,'智慧校园安防解决方案','智慧教育','','[]','覆盖校园全场景的安防与信息化方案，构建「事前预防、事中处置、事后追溯」的平安校园体系。','智慧校园安防解决方案围绕校园安全核心诉求，建设视频监控、人脸识别、入侵报警、访客管理、电子巡查等子系统，并联动应急广播与指挥中心，构建全方位、多层次的校园安全防护体系，为师生营造安全的学习生活环境。','适用于中小学、高校、幼儿园等教育场景，重点解决校园周界安全、出入口管理、重点区域监控、突发事件处置等问题。','前端感知（摄像机/报警柱/门禁）→ 智能分析（人脸/行为识别）→ 安防综合管理平台 → 应急指挥与移动端联动','[\"重点区域 24 小时智能值守\",\"异常事件自动告警推送\",\"访客出入全程留痕\",\"应急事件一键联动\"]','[]','[]',1,2,'智慧校园安防解决方案','','','2026-08-29 17:08:57','2026-08-29 17:08:57'),(4,'智慧园区解决方案','智慧园区','','[]','面向产业园区、办公园区的一体化智慧运营方案，实现安防、能耗、停车、访客等场景的数字化管理。','智慧园区解决方案以「1个平台 + N个应用」为架构，融合物联网感知、视频AI、大数据分析等技术，建设智慧安防、智慧通行、智慧能耗、智慧办公等应用，全面提升园区运营效率与安全水平。','适用于产业园区、科技园区、办公园区、物流园区等场景，解决安防管理分散、能耗浪费、通行效率低、运营数据不透明等痛点。','感知层（IPC/门禁/传感器）→ 网络层（有线/无线/物联网）→ 平台层（驰耀物联云平台）→ 应用层（安防/能耗/通行/办公）→ 展示层（运营大屏/移动端）','[\"安防事件响应时间缩短 60%\",\"园区能耗降低 20%\",\"通行效率提升 45%\",\"运营数据一屏可视\"]','[]','[]',1,1,'智慧园区解决方案','','','2026-08-29 17:08:57','2026-08-29 17:08:57'),(5,'智慧校园安防解决方案','智慧教育','','[]','覆盖校园全场景的安防与信息化方案，构建「事前预防、事中处置、事后追溯」的平安校园体系。','智慧校园安防解决方案围绕校园安全核心诉求，建设视频监控、人脸识别、入侵报警、访客管理、电子巡查等子系统，并联动应急广播与指挥中心，构建全方位、多层次的校园安全防护体系，为师生营造安全的学习生活环境。','适用于中小学、高校、幼儿园等教育场景，重点解决校园周界安全、出入口管理、重点区域监控、突发事件处置等问题。','前端感知（摄像机/报警柱/门禁）→ 智能分析（人脸/行为识别）→ 安防综合管理平台 → 应急指挥与移动端联动','[\"重点区域 24 小时智能值守\",\"异常事件自动告警推送\",\"访客出入全程留痕\",\"应急事件一键联动\"]','[]','[]',1,2,'智慧校园安防解决方案','','','2026-08-29 17:08:57','2026-08-29 17:08:57'),(6,'企业数字化监控解决方案','智能制造','','[]','面向制造企业的生产可视化与设备联网监控方案，让生产数据实时在线、设备状态一目了然。','企业数字化监控解决方案通过对生产设备、产线、能耗的数据采集与联网，构建企业数字化监控平台，实现生产进度可视化、设备状态实时监控、能耗精细化管理与异常自动告警，助力制造企业降本增效、数字化转型。','适用于生产制造、仓储物流、能源化工等企业场景，解决设备孤岛、生产黑箱、能耗浪费、故障响应慢等痛点。','设备层（PLC/传感器/网关）→ 边缘计算（协议解析/数据清洗）→ 监控平台（实时监控/告警/报表）→ 管理应用（移动端/大屏）','[\"设备联网率提升至 95%\",\"故障响应时间缩短 70%\",\"能耗数据精细到工序\",\"生产报表自动生成\"]','[]','[]',1,3,'企业数字化监控解决方案','','','2026-08-29 17:08:57','2026-08-29 17:08:57'),(7,'智慧校园安防解决方案','智慧教育','','[]','覆盖校园全场景的安防与信息化方案，构建「事前预防、事中处置、事后追溯」的平安校园体系。','智慧校园安防解决方案围绕校园安全核心诉求，建设视频监控、人脸识别、入侵报警、访客管理、电子巡查等子系统，并联动应急广播与指挥中心，构建全方位、多层次的校园安全防护体系，为师生营造安全的学习生活环境。','适用于中小学、高校、幼儿园等教育场景，重点解决校园周界安全、出入口管理、重点区域监控、突发事件处置等问题。','前端感知（摄像机/报警柱/门禁）→ 智能分析（人脸/行为识别）→ 安防综合管理平台 → 应急指挥与移动端联动','[\"重点区域 24 小时智能值守\",\"异常事件自动告警推送\",\"访客出入全程留痕\",\"应急事件一键联动\"]','[]','[]',1,2,'智慧校园安防解决方案','','','2026-08-29 17:08:57','2026-08-29 17:08:57'),(8,'企业数字化监控解决方案','智能制造','','[]','面向制造企业的生产可视化与设备联网监控方案，让生产数据实时在线、设备状态一目了然。','企业数字化监控解决方案通过对生产设备、产线、能耗的数据采集与联网，构建企业数字化监控平台，实现生产进度可视化、设备状态实时监控、能耗精细化管理与异常自动告警，助力制造企业降本增效、数字化转型。','适用于生产制造、仓储物流、能源化工等企业场景，解决设备孤岛、生产黑箱、能耗浪费、故障响应慢等痛点。','设备层（PLC/传感器/网关）→ 边缘计算（协议解析/数据清洗）→ 监控平台（实时监控/告警/报表）→ 管理应用（移动端/大屏）','[\"设备联网率提升至 95%\",\"故障响应时间缩短 70%\",\"能耗数据精细到工序\",\"生产报表自动生成\"]','[]','[]',1,3,'企业数字化监控解决方案','','','2026-08-29 17:08:57','2026-08-29 17:08:57'),(9,'企业数字化监控解决方案','智能制造','','[]','面向制造企业的生产可视化与设备联网监控方案，让生产数据实时在线、设备状态一目了然。','企业数字化监控解决方案通过对生产设备、产线、能耗的数据采集与联网，构建企业数字化监控平台，实现生产进度可视化、设备状态实时监控、能耗精细化管理与异常自动告警，助力制造企业降本增效、数字化转型。','适用于生产制造、仓储物流、能源化工等企业场景，解决设备孤岛、生产黑箱、能耗浪费、故障响应慢等痛点。','设备层（PLC/传感器/网关）→ 边缘计算（协议解析/数据清洗）→ 监控平台（实时监控/告警/报表）→ 管理应用（移动端/大屏）','[\"设备联网率提升至 95%\",\"故障响应时间缩短 70%\",\"能耗数据精细到工序\",\"生产报表自动生成\"]','[]','[]',1,3,'企业数字化监控解决方案','','','2026-08-29 17:08:57','2026-08-29 17:08:57